c(33, "§3.1 table (verbatim); §3.1", "data-caveat", "Prioritised theme table with E6 segment rates (verbatim): " + table("## 3.1 The prioritised picture", 0) + " — praise and a price objection share 304 reviews (3.92%): 'great app, too expensive / three items is too few' is the typical 3–4★ review; negatives outside monetization U_NEG_PRODUCT 514 + U_BUG_ANY 257 touch 732 (9.43%).", "n/a", "mixed", "32 ranked themes; praise∩price 304 (3.92%); non-money negatives 732 (9.43%)", "none", "table", "generalisable", ["7243490138"], "", "")

c(34, "§3.1 (E6 shifts)", "timeline", "Subscription-era (E6, 906 reviews) segment rates diverge from the corpus: MON_SUBSCRIPTION 4.4% (0.52% overall), PR_DEV 6.7% (3.45%), PR_CHAINS 3.2% (1.66%), BUG_PURCHASE 1.5% (0.70%), SUP_NONE 1.0% (0.26%); while MON_PRICE fell to 2.0% (3.94%), MON_FREE_LIMIT 1.5% (3.22%), U_NEG_PRODUCT 3.3% (6.62%), REQ_IPAD 0.7% (1.58%), NEG_ADS 0.0%.", "product matured; subscription introduced", "mixed", "E6 n=906; see rates", "none", "table", "app-specific", ["13889612885"], "", "E6 2023–2026")

c(35, "§3.2 table (verbatim); §3.2 bullets", "insight", "What users value (verbatim): " + table("## 3.2 What users value", 0) + " — why it works: logging costs seconds so it survives ('almost 9 years since my last review and 13 since the first'; 'I track 30+ items in under 2 minutes'); honesty through colour ('keeps me from fooling myself into thinking I did better than I really did'; 'I hate to break a winning steak'); good and bad habits in one grid ('it reverses the red/green colours for yes and no'); skip without guilt ('skip option for when you have days where you need to skip without breaking your chain'); chains from 2015-11 (PR_CHAINS 129, 56 in E4: 'Chains is going to change my life'); the developer (PR_DEV 268, 3.45%, rising 2.1% E1 → 6.7% E6, named and thanked for a decade of maintenance: 'Through steady updates, this continues to be the best habit/task tracking app').", "free core loop", "praise", "41 praise codes; PR_STICKY 325 (4.19%); PR_BEST 548 (7.06%); PR_RECOMMEND 503 (6.48%); PR_UPDATE 255 (3.28%); PR_DEV 2.1% E1 → 6.7% E6", "build-free", "High-priority", "generalisable", ["10961979664", "1618497915", "1501749022", "6656271875", "2033057159", "1430830624", "1290249480", "4420297480"], "", "")

c(36, "§3.2 (red cell honesty)", "insight", "Honesty through colour is the motivator — the red cell, not a reward: 'keeps me from fooling myself into thinking I did better than I really did' (5★); 'I hate to break a winning steak' (gb 5★); PR_ACCOUNTABILITY 477 (6.14%, mean 4.86★).", "shows 'no' days in red on a grid", "praise", "PR_ACCOUNTABILITY 477 / 6.14% / 4.86; PR_MOTIVATION 509 / 6.56%", "build-free", "High-priority", "generalisable", ["1501749022", "6656271875"], "", "")

c(37, "§3.2 (skip); §2.1; §3.6 (requests that stop)", "feature", "Skip without guilt — a third state that keeps the chain: PR_SKIP 99 (1.28%, mean 4.66★); REQ_SKIP (7, 2011-10-05 → 2011-11-28) ends before skip praise begins (2012-05-18) — shipping killed the request; but the same state is misused as a scheduling workaround for missing frequency (see U_FLEX_REQ).", "free skip state since 2012", "praise", "PR_SKIP 99 / 1.28% / 4.66; REQ_SKIP 7 ended 2011-11", "build-free", "Meaningful", "generalisable", ["1430830624", "2382746040"], "", "")

c(38, "§3.2 (good/bad habits)", "feature", "Good AND bad habits in one grid, colours inverting for habits to avoid: PR_YESNO 73 (0.94%) — 'it reverses the red/green colours for yes and no' (gb 5★); REQ_NEUTRAL_HABIT 5 want a neutral kind.", "free good/bad habit types", "praise", "PR_YESNO 73 / 0.94% / 4.84; REQ_NEUTRAL_HABIT 5", "build-free", "Emerging", "generalisable", ["2033057159"], "", "")

